      l.readers[id] = { id: id, order: order, reads: reads, raw: onSet, apply: wrapped };   /* Phase 132i */
      ctx.flags.forEach(function(f){
        var r = l.raisers[f] || (l.raisers[f] = []);
        if(!r.length && flags0.indexOf(f) >= 0) l.outside[f] = true;   /* already on the session, and no question raised it */
        if(r.indexOf(id) === -1) r.push(id);
        flags.push(f); });
      if(writes.length || lines.length || flags.length) owned.set(s, { writes: writes, lines: lines, flags: flags });
