        if(!prev || !l) return false;
        var view = Object.assign({}, s);
        prev.writes.forEach(function(w){ var stack = l.writes[w.k];
          if(stack && stack[stack.length - 1] === w){ if(w.hadBefore) view[w.k] = copy(w.before); else delete view[w.k]; } });
