// ============================================================================
//  THE ESTIMATE ENGINE
// ============================================================================
function runEngine(s){
  const A=[]; s.assumptions.forEach(a=>A.push(a));
  CB_PLANT.bandCaveats().forEach(function(c){ A.push(c); }); // D-1 — List C is not qualification
  CB_S25.caveats(s, A); // D-4 — alterations incidental to installing plant
  let base = s.base_amount||0;
  // SD-1 (12975610449) — the transaction tax paid on the purchase, added to the
  // figure the claim is apportioned from. OFF by default; the switch is
  // CB_CTA.transaction_tax_in_base and it waits on the stamp-duty question in
  // the adviser pack. Placed HERE, ahead of the grant and contribution strips,
  // so a grant-funded share of the consideration carries the tax paid on it out
  // in the same proportion. Adds nothing at all unless the client stated an
  // amount — an unknown never enlarges a claim.
  base = CB_ACQ.addToBase(s, base, A, function(f){ pushFlag(s,f); });
  const grant = s.grant_fraction||0;
  // GC-1 (13014647417) — with CB_CTA.grant_after_ceilings on, the spend is left
  // whole here and the grant's share comes off after the ceilings instead; see
  // the note under Stage 4. The sentence pushed below is the same in both orders.
  const __grantLate = CB_CTA.grant_after_ceilings && grant>0;
  if(grant>0){ if(!__grantLate) base=base*(1-grant); A.push("grant-funded spend removed ("+Math.round(grant*100)+"%)"); }
  // F-7 — a landlord/pension contribution is captured as a number and actually deducted,
  // not just noted "to be quantified"; same mechanism as the grant strip above (s.532).
  // F-6 (12852267228) — does a CONNECTED contributor's payment reduce the
  // occupier's own spend? OFF by default; the switch is
  // CB_CTA.connected_contributor_no_reduction and it waits on F-Q1.
  // s.537(2)(c) may block the contributor from claiming contribution
  // allowances at all, and if it does, s.532 arguably has nothing to bite on
  // and the occupier's spend stands in full. Fires only on an explicit
  // "connected: yes" — unknown leaves the deduction in place.
  // This is NOT the F-3 question and does not share its switch.
  const __contribBlocked = CB_CTA.connected_contributor_no_reduction &&
                           s.contributor_connected === "yes";
  if(__contribBlocked && (s.landlord_contrib_fraction||0) > 0){
    A.push("the contribution towards the fit-out came from someone connected to you. It has NOT been taken off your qualifying spend, because a connected contributor is barred from claiming contribution allowances on it (s.537(2)(c)) and on that reading the spend stays yours in full \u2014 an unconnected contribution would still come off");
    pushFlag(s,"CONNECTED CONTRIBUTION NOT DEDUCTED (F-6) \u2014 the occupier's spend has been left standing in full on the s.537(2)(c) reading. This is a SWITCHED position (CB_CTA.connected_contributor_no_reduction) and stands only if F-Q1 has been answered that way; the connection must be evidenced, and the contributor must not also be claiming.");
    // F-8 (12852259225) WITH F-6 — PHASE 132, 14 September 2026. CAA 2001 s.536,
    // read on legislation.gov.uk that day, is the exception that leaves the
    // spend standing, and s.536(6) disapplies it for Part 2A: the contribution
    // still reduces any structures and buildings allowance claim. s.536(2) needs
    // a contributor that is not a public body, and s.536(3)(b) one that cannot
    // deduct the payment in its own profits. Words only, inside the switched path.
    A.push("structures and buildings allowance is treated differently: the exception that leaves this spend standing does not apply to that allowance (CAA 2001 s.536(6)), so the contribution still reduces any structures and buildings allowance claim on the same works");
    pushFlag(s,"CONFIRM THE CONTRIBUTOR IS NOT A PUBLIC BODY (F-6, F-8) — the spend is left standing only where the contributor is not a public body such as an NHS body, an integrated care board or a local authority (s.536(2)), and cannot deduct the payment in its own profits (s.536(3)(b)). The contribution still reduces any structures and buildings allowance claim (s.536(6)).");
  }
  const landlordContrib = __contribBlocked ? 0 : (s.landlord_contrib_fraction||0);
  if(landlordContrib>0){ base=base*(1-landlordContrib);
    A.push("landlord/pension contribution to the fit-out removed ("+Math.round(landlordContrib*100)+"% of spend) — reduces qualifying spend (s.532); the contributor may separately claim contribution allowances (s.537–538)"); }

  // dwelling factor — inert for a trade except a residential-above carve-out
  // E-5 (12851716860) — should a flat held FOR THE PURPOSES OF THE TRADE be
  // stripped out at all? OFF by default; the switch is CB_CTA.trade_not_s35
  // and it waits on E-Q6. s.15(3) arguably keeps s.35(1) away from a trade or
  // profession, in which case a manager's or practitioner's flat held for the
  // trade is not a dwelling-house restriction at all. A flat LET to a third
  // party is a different thing and still comes out. Fires only on an explicit
  // "trade_purpose" — an unstated reason leaves the strip in place.
  const __tradeFlat = CB_CTA.trade_not_s35 && s.dwelling_setting==="mixed" &&
                      s.residential_purpose === "trade_purpose";
  if(__tradeFlat){
    A.push("the residential part is held for the purposes of the practice itself \u2014 staff or practitioner accommodation, not a separate letting \u2014 so it has NOT been taken out of the figure. Had it been let to someone else it would have come out on its own footing");
    pushFlag(s,"TRADE-PURPOSE FLAT NOT STRIPPED (E-5) \u2014 the residential part has been left in the base on the s.15(3) reading. This is a SWITCHED position (CB_CTA.trade_not_s35) and stands only if E-Q6 has been answered that way; the trade purpose must be evidenced.");
  }
  let f=1;
  if(s.dwelling_setting==="mixed" && !__tradeFlat){ const r=s.residential_fraction||0; f=(1-r);
    A.push("residential part ("+Math.round(r*100)+"%) taken out \u2014 the practice is a trade, so the clinical part is unrestricted"); }
  const B=base*f;

  // band (dominant trigger by midpoint) — note the BASE differs: fit-out spend vs whole build cost
  const norm=t=> t==="purchase"?"purchase": t==="new_build"?"new_build":"refurb_fitout";
  const triggers=(s.trigger.length?s.trigger:["fitout"]).map(norm);
  let dom=triggers[0];
  triggers.forEach(t=>{ if(mid(...YIELD_BAND.dental[t])>mid(...YIELD_BAND.dental[dom])) dom=t; });
  let [qLo,qHi]=YIELD_BAND.dental[dom];
  if(dom==="new_build") A.push("new-build band applied to the whole build cost (the structure dilutes the plant share; the residue is SBA)");
  else if(dom==="refurb_fitout") A.push("fit-out band applied to the fit-out spend");

  // conditioning
  if(dom==="purchase"){
    if(s.earlier_entitled_owner==="yes"){
      A.push("an earlier entitled owner was identified further back in the chain \u2014 s.185 looks past the non-entitled seller, so this is not treated as a fresh best-case claim" +
        (s.earlier_disposal_value ? " \u2014 capped at the disposal value fixed at that earlier sale" : " \u2014 the cap cannot yet be sized without that owner's disposal value, so the full range is shown pending it"));
    } else if(s.prior_owner_entitled==="no" && s.earlier_entitled_owner==="unsure"){ A.push("seller not entitled, but an earlier entitled owner further back cannot be ruled out \u2014 full range shown pending the ownership history (s.185)"); }
    else if(s.prior_owner_entitled==="no" || s.prior_owner_claimed==="no"){ qLo=mid(qLo,qHi); A.push("seller never able to claim \u2014 upper half used (best case)"); }
    else if(s.prior_owner_claimed==="yes" && s.prior_owner_entitled==="yes"){ qHi=mid(qLo,qHi); A.push("a previous owner could and did claim \u2014 lower half, before any cap"); }
    else A.push("entitlement history not yet known \u2014 full range shown");
    if(s.seller_pre_2008){ qLo*=1.15; qHi*=1.15; A.push("seller bought pre-2008 \u2014 ~15% integral-features uplift"); }
  } else {
    if(s.scale==="single"){ qHi=mid(qLo,qHi); A.push("single-surgery practice \u2014 lower half of the fit-out band"); }
    if(s.scale==="multi"||s.scale==="specialist"){ qLo=mid(qLo,qHi); A.push((s.scale==="specialist"?"specialist":"multi-surgery")+" practice \u2014 fixture-denser, upper half used"); }
  }

  let QE_lo=B*qLo, QE_hi=B*qHi;

  // GC-1 (13014647417) — WHEN THE GRANT COMES OFF, relative to the ceilings.
  // OFF by default; the switch is CB_CTA.grant_after_ceilings and it waits on
  // the grant-and-ceiling question for the tax adviser. Switched OFF, Stage 1
  // has already taken the grant off the SPEND, the ceilings below are applied
  // to what is left, and __takeGrantLate does nothing — today's order.
  // Switched ON, Stage 1 left the spend whole, and the grant's share comes off
  // the FIGURE once the disposal-value, election and s.187A ceilings have been
  // applied, so a ceiling that holds the figure down no longer hides the grant.
  // Where no ceiling binds the two orders give the same figure, because
  // everything from Stage 1 to here is proportional to the base.
  // It comes off BEFORE the C-4 "+ I" and D-5 add-ons, which no grant reaches in
  // either order, so this switch moves a figure only where a ceiling binds, and
  // the flag is raised only where one did. THE ONLY SWITCH THAT CAN ONLY MAKE A
  // CLAIM SMALLER.
  const __preCeiling = [QE_lo, QE_hi];
  let __grantLateDone = false;
  const __takeGrantLate = function(){
    if(!__grantLate || __grantLateDone) return;
    __grantLateDone = true;
    const __bound = Math.abs(QE_lo-__preCeiling[0]) > 1e-6 || Math.abs(QE_hi-__preCeiling[1]) > 1e-6;
    QE_lo = QE_lo*(1-grant); QE_hi = QE_hi*(1-grant);
    if(__bound) pushFlag(s,"GRANT TAKEN OFF AFTER THE CEILING (GC-1) \u2014 a ceiling on what may be claimed held this figure down, and the grant-funded share ("+Math.round(grant*100)+"%) has then been taken off the capped figure rather than off the spend before the ceiling was applied, so the grant has reduced the claim even though the ceiling bound. This is a SWITCHED position (CB_CTA.grant_after_ceilings) and stands only if the tax adviser has answered the grant-and-ceiling question that way.");
  };

  // F-10 (12852259255) — s.185(1)(c) and s.187A(1)(c) both exclude plant a
  // past owner held AS A RESULT OF s.538. Where that owner's entitlement arose
  // only through a contribution allowance, neither cap may engage at all.
  // OFF by default; the switch is CB_CTA.s538_carveout and it waits on F-Q4.
  // Fires only on an explicit "contribution_only" route — an unknown route
  // leaves both caps in force.
  // NOT the same question as F-3, and NOT the same switch.
  const __s538Carve = CB_CTA.s538_carveout &&
                      s.past_owner_entitlement_route === "contribution_only";

  // E-8 (12851716705) — was a landlord who was themselves barred by s.35 ever
  // "entitled to claim"? If not, s.187A does not engage on a purchase from them.
  // OFF by default; the switch is CB_CTA.s187a_needs_entitled_owner and it
  // waits on E-Q4. Fires only where the bar is positively established.
  // PHASE 132, 14 SEPTEMBER 2026 - THE s.185 NARROWING OF 28 AUGUST 2026:
  // s.187A is disengaged only where NO owner in the chain was entitled, not
  // merely the seller, so an earlier entitled owner must be KNOWN to be absent
  // too. "Not sure" and no answer never fire it (N4). Whether an owner entitled
  // only through s.538 counts as "entitled" here is E-Q4 with F-Q4, not code.
  // This REMOVES a cap, so the s.185 position it leaves behind is flagged as
  // unresolved rather than quietly treated as uncapped.
  const __s187aOff = CB_CTA.s187a_needs_entitled_owner &&
                     s.prior_owner_s35_barred === true &&
                     s.earlier_entitled_owner === "no";
  if(__s187aOff && dom==="purchase"){
    A.push("the landlord you bought from could never have claimed capital allowances on these fixtures themselves, because the law that bars a claim on dwellings barred them. On that reading the second-hand fixtures rules do not apply to your purchase at all, so nothing about their claim history limits yours");
    pushFlag(s,"s.187A NOT ENGAGED (E-8) \u2014 the seller was barred by s.35 and so was arguably never entitled to claim, which takes this purchase outside s.187A. The s.185 ceiling on these fixtures is therefore UNRESOLVED, not absent \u2014 it has not been applied and it has not been ruled out. This is a SWITCHED position (CB_CTA.s187a_needs_entitled_owner) and stands only if E-Q4 has been answered that way.");
  }
  if(__s538Carve && __s187aOff){
    pushFlag(s,"BOTH CARVE-OUTS FIRE (E-Q4 + F-Q4) \u2014 the s.538 route carve-out and the s.35-barred-seller carve-out have both removed a ceiling from the same figure, so nothing is left holding it down. These two questions compound and must be answered together, not one at a time.");  /* E-8 12851716705 + F-10 12852259255 — board ids kept HERE, not in the client flag (Phase 53) */
  }
  if(__s538Carve && dom==="purchase" && s.earlier_entitled_owner==="yes"){
    A.push("the earlier owner only became entitled to allowances on these fixtures because somebody contributed towards their cost, rather than by buying or installing them. Where that is how the entitlement arose, the statutory ceiling that would otherwise cap your claim at their figure does not appear to reach these fixtures, so it has not been applied");
    pushFlag(s,"s.538 CONTRIBUTION-ROUTE CARVE-OUT APPLIED (F-10) \u2014 the s.185 and s.187A ceilings have not been applied, because the past owner's entitlement arose only under a contribution allowance. This is a SWITCHED position (CB_CTA.s538_carveout) and stands only if F-Q4 has been answered that way; the contribution route must be evidenced, not assumed.");
  }
  if(dom==="purchase" && !__s538Carve && s.earlier_entitled_owner==="yes" && s.earlier_disposal_value){
    const __dv = +s.earlier_disposal_value;
    QE_lo = Math.min(QE_lo, __dv); QE_hi = Math.min(QE_hi, __dv);
  }

  // PHASE 154a1 (line 13), R-B1 — THE POOLING REQUIREMENT (s.187A(4)). A seller
  // KNOWN to have been able to claim who never claimed (so never pooled), or
  // whose claim history is unknown: nil, or unresolved with nil at the bottom.
  // The caps block below runs only on a seller who claimed, so this is the
  // only place such a purchase meets s.187A. CB_S187A.poolingAssess.
  if(dom==="purchase" && s.prior_owner_claimed!=="yes" && !__s187aOff && !__s538Carve){
    var __pool = CB_S187A.poolingAssess(s);
    if(__pool){
      s.s187a = __pool;
      var __pr = CB_S187A.applyOutcome(__pool, QE_lo, QE_hi, A, function(f){ pushFlag(s,f); });
      QE_lo = __pr[0]; QE_hi = __pr[1];
    }
  }

  // caps
  if(dom==="purchase" && s.prior_owner_claimed==="yes" && !__s187aOff && !__s538Carve){
    // C-1 — an ASSERTED election is not an election. s.187B(1) puts the
    // burden on the client, and a document failing the s.201 content
    // requirements is not an election at all.
    var __el = CB_ELECTION.assess(s);
    var __capped = CB_ELECTION.applyCap(__el, QE_lo, QE_hi, A, function(f){ pushFlag(s,f); });
    QE_lo = __capped[0]; QE_hi = __capped[1];

    // A-6/A-5/A-1/A-4 — s.187A decides whether there is any qualifying
    // expenditure on the second-hand fixtures at all, and on which of two
    // clocks. Runs AFTER the election cap so that where s.187A(3) returns nil
    // it is the last word on the range, not something a later cap can widen.
    // Both are minimums, so the numeric result is the same either way; the
    // ordering is for the narrative the client is given.
    var __a187 = CB_S187A.assess(s);
    s.s187a = __a187;
    var __s187 = CB_S187A.applyOutcome(__a187, QE_lo, QE_hi, A, function(f){ pushFlag(s,f); });
    QE_lo = __s187[0]; QE_hi = __s187[1];

    // GC-1 — with that switch on, the grant's share comes off HERE: after the
    // election and s.187A, before the C-4 "+ I" add-on below.
    __takeGrantLate();

    // C-4 (12840979279) — s.185(3) "maximum allowable amount = disposal value
    // PLUS the buyer's own s.25 expenditure". OFF by default; the switch is
    // CB_CTA.s185_plus_own_s25 and it waits on C-Q6. Max(), not sum: where
    // both an election ceiling and a disposal-value ceiling bit, it is the
    // same alteration spend and it is added once.
    var __plusI = Math.max(CB_S25.capUplift(s, __el), CB_S25.capUplift(s, __a187));
    if(__plusI > 0){
      QE_lo += __plusI; QE_hi += __plusI;
      A.push("the spend on the building alterations needed to install the plant — your own, not the seller’s — has been added ON TOP of that ceiling rather than absorbed into it, because s.185(3) sets the maximum at the earlier owner’s disposal value plus your own alteration expenditure");
      pushFlag(s,"s.185(3) “+ I” APPLIED (C-4) — the buyer’s own s.25 alteration spend has been added to the statutory ceiling. This is a SWITCHED position (CB_CTA.s185_plus_own_s25) and stands only if C-Q6 has been answered that way.");
    }
    if(__a187.pooling === false) A.push("the owner who last claimed stopped owning the fixtures early enough in the life of these rules that they were not required to have pooled the expenditure first (FA 2012 Sch 10 para 13(2))");

    s.election_outcome = __el;
  // C-7 — s.203 runs against our own client and our work triggers it.
  s.s203 = CB_ELECTION.s203Position(s, __el);
  if(s.s203.position === "notification_may_be_required"){
    pushFlag(s,"s.203 NOTIFICATION \u2014 " + s.s203.action);
    A.push("because an election has been identified, a tax return you have already filed may have become incorrect \u2014 there is a three-month window to tell HMRC, and whoever signs your filing position — your accountant or tax adviser, or you if you have neither — should be asked about it");
  }
  }

  // GC-1 — and where the caps block above did not run, the disposal-value
  // ceiling was the last one, so the grant's share comes off here instead. A
  // no-op if it already came off inside the block, or if the switch is off.
  __takeGrantLate();

  // tax saving
  // D-5 (12843022045) — Urenco, "expenditure on the provision of" plant.
  // OFF by default; the switch is CB_CTA.urenco_provision_of and it waits on
  // D-Q4. Sits AFTER the s.185 / s.187A caps on purpose: this is the client’s
  // own new spend on their own plant, not expenditure on second-hand fixtures,
  // so neither cap reaches it. De-duplicated inside provisionUplift against any
  // s.25 alteration line for the same pound.
  var __prov = CB_S25.provisionUplift(s);
  if(__prov > 0){
    QE_lo += __prov; QE_hi += __prov;
    A.push("the cost of installing and commissioning the plant has been included in its own right, as expenditure on the provision of the plant, rather than only where it could be tied to a named element of the building; where you had already entered the same spend as an installation alteration it has been counted once, not twice");
    pushFlag(s,"URENCO “PROVISION OF” APPLIED (D-5) — installation and commissioning spend admitted in its own right. This is a SWITCHED position (CB_CTA.urenco_provision_of) and stands only if D-Q4 has been answered that way.");
  }

  // S33-1 (Phase 132) - CAA 2001 s.33B, integral features: more than half the
  // replacement cost, alone (s.33B(2)) or with further work on the same system
  // in the 12 months beginning with the first (s.33B(3) and (4)), is a
  // replacement - capital, special rate. OFF by default; the switch is
  // CB_CTA.s33b_aggregation and it waits on G-Q3 and G-Q4. Beside D-5 for the
  // same reason: the client's own spend on their own building's systems, which
  // neither the s.185 nor the s.187A cap reaches. The words and flags are
  // CB_S33B's, so five flows cannot say it five ways.
  var __s33b = CB_S33B.uplift(s, A, function(f){ pushFlag(s,f); });
  if(__s33b > 0){ QE_lo += __s33b; QE_hi += __s33b; }

  let rateKey = s.claimant_type==="company"?"company":CB_RATES.unincKey(s, function(f){ pushFlag(s,f); });   // RH-1: the same key as the property proxy while CB_CTA.scottish_rate_from_main_home is off
  const [rLo,rHi]=(rateKey==="company")?CB_RATES.companyRange(s, QE_lo, QE_hi):MARGINAL_RATE[rateKey];   // AC-1 (Phase 132): MARGINAL_RATE.company itself while CB_CTA.ct_rate_from_associated_companies is off
  const TS_lo=QE_lo*rLo, TS_hi=(rateKey==="company")?QE_hi*rHi:CB_RATES.unincHigh(s, rateKey, CB_RATES.taxYearOf(s.accounting_period_end), QE_hi);   // TP-1 (Phase 132): QE_hi at the shipped top rate while CB_CTA.income_tax_taper_band is off
  A.push(CB_RATES.describe(rateKey, function(f){ pushFlag(s,f); }, s));   // LEG-E1; the AC-1 and TP-1 words follow their switches
  A.push(CB_RATES.basisNote());

  // amendment window (derived, board item 12829962267) + gated cash benefit
  // (CB_CASH, board items 12804375487/550)
  const __win = CB_CASH.deriveAmendmentWindow(s);
  if(__win.known){
    s.return_in_time = __win.inTime;
    A.push(CB_CASH.describeWindow(s, __win));   // Phase 129b: the year the money was spent in
  } else if(__win.ambiguous){
    /* PHASE 132 (line 20) - A WINDOW OPEN ON ONE PARTNERSHIP FILING DATE AND
       SHUT ON THE OTHER IS NOT OPEN. Whether a partner is a company is not
       known and today falls between the two dates, so a fallback "in time"
       answer cannot stand in for that fact: it is set aside, and no refund
       route or first-year relief rests on it (N4). LIVE, close-only. */
    if(s.return_in_time === true) delete s.return_in_time;
    A.push(CB_CASH.describeWindow(s, __win));
  }
  const __cash = CB_CASH.computeCashBenefit(s, TS_lo, TS_hi, function(f){ pushFlag(s,f); });
  __cash.reasons.forEach(function(r){ A.push(r); });

  // speed note (relief levers). GC-1: with that switch on Stage 1 left the
  // grant inside `base`, so the AIA test reads the spend net of it, as it
  // always has - the switch moves no sentence here.
  let speed = s.return_in_time
    ? (((__grantLate ? base*(1-grant) : base)<=1000000)
        ? "Most of this sits within the \u00a31m Annual Investment Allowance, so with the return open it can be relieved at 100% in year one."
        : (s.claimant_type==="company"
            ? "Over the \u00a31m AIA: Full Expensing (100%, new main-rate plant) and the 50% allowance (new special-rate) bring most of it forward; writing-down allowances on the balance and any second-hand plant."
            : "Over the \u00a31m AIA: the 40% first-year allowance on new main-rate plant, then writing-down allowances."))
    : (s.return_in_time === false
        ? "The relief isn\u2019t lost, but with the return out of time it comes through as writing-down allowances over future years."
        : CB_CASH.SPEED_WINDOW_UNKNOWN);   // Phase 129b: a window not known is not out of time

  if(__cash.mechanism === CB_CASH.MECHANISM.AMEND){
    speed += " Because this reaches an already-filed return, the cash benefit here can include an actual refund from HMRC, not just a lower bill.";
  } else if(__cash.mechanism === CB_CASH.MECHANISM.LOSS_CARRYBACK){
    speed += " Because the claim increases a loss carried back against an earlier year's profits, part of this can also come back as a repayment of tax paid for last year.";   /* Phase 153b, Word question 92: a loss carried back repays an earlier year's tax - Rulebook A s.4's exception to "refund" */
  } else if(__cash.mechanism === CB_CASH.MECHANISM.CURRENT_YEAR){
    speed += " This reaches a return that hasn't been filed yet, so it reduces what's due rather than producing a refund of tax already paid.";
  } else if(__cash.mechanism === CB_CASH.MECHANISM.WDA_FORWARD){
    speed += " This isn't a refund, it reduces future tax bills as the writing-down allowances are used.";
  }

  return { outcome: s.flags.length?"referral":"estimate", QE:[QE_lo,QE_hi], TS:[TS_lo,TS_hi],
    cash:__cash.cash, cashRoute:__cash.route, cashBlocked:__cash.blocked, cashGates:__cash.gate,
    pool: CB_POOL.split(s, QE_lo, QE_hi, A), // D-2 — main-rate / special-rate split
    flags:s.flags, assumptions:A, speed, lrr:(s.lrr===true && s.lrr_polluter==="no")   /* Phase 132j - the land remediation panel needs a KNOWN "no" to D23 (N4); no figure reads lrr */, grant:grant>0, sipp:s.ownership==="sipp" };
}
const gbp=n=>"\u00a3"+Math.round(n).toLocaleString("en-GB");


/* @@CAPREBATE-SLICE-CLOSE@@ */

module.exports = {
  sector: "dental",
  runEngine: runEngine,
  Q: Q,
  YIELD_BAND: YIELD_BAND,
  pushFlag: pushFlag
};
